/* ---------- small building blocks ---------- */

function SectionHeading({ eyebrow, title }) {
  return (
    <div className="vsd-heading">
      {eyebrow && <div className="vsd-eyebrow">{eyebrow}</div>}
      <h2>{title}</h2>
      <div className="vsd-rule" />
    </div>
  );
}

function TrustTable({ rows }) {
  return (
    <div className="vsd-table-wrap">
      <table className="vsd-table">
        <thead>
          <tr>
            <th>अ. नं.</th>
            <th>नाम</th>
            <th>पद</th>
            <th>गांव</th>
            <th>मोबाईल नं.</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((m) => (
            <tr key={m.sr}>
              <td>{m.sr}</td>
              <td>{m.name}</td>
              <td>{m.desig}</td>
              <td>{m.village}</td>
              <td>{m.mobile}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function Modal({ title, onClose, children }) {
  return (
    <div className="vsd-modal-backdrop" onClick={onClose}>
      <div className="vsd-modal" onClick={(e) => e.stopPropagation()}>
        <div className="vsd-modal-head">
          <h3>{title}</h3>
          <button className="vsd-close" onClick={onClose}>×</button>
        </div>
        {children}
      </div>
    </div>
  );
}

function BankModalContent({ org }) {
  return (
    <div className="vsd-card" style={{ margin: 0, boxShadow: "none", border: "none", padding: 4 }}>
      <p>
        {org.bank.accountName}
        <br />
        Bank Name: {org.bank.bankName} &nbsp; Branch: {org.bank.branch}
        <br />
        IFSC Code: {org.bank.ifsc}
      </p>
    </div>
  );
}

function ContactModalContent({ org }) {
  return (
    <div className="vsd-card" style={{ margin: 0, boxShadow: "none", border: "none", padding: 4 }}>
      {org.contacts.map((c, i) => (
        <p key={i} style={{ margin: "4px 0" }}>{c}</p>
      ))}
      <p style={{ marginTop: 10 }}>Email: {org.email}<br />Website: {org.website}</p>
    </div>
  );
}

function AddressModalContent({ org }) {
  return (
    <div className="vsd-card" style={{ margin: 0, boxShadow: "none", border: "none", padding: 4 }}>
      <p>{org.address}</p>
    </div>
  );
}



