/* ---------- Acharya Shree Chikitsalaya ---------- */

function ChikitsalayaSection() {
  const [tab, setTab] = useState("intro");
  const [modal, setModal] = useState(null); // 'trust' | 'bank' | 'contact' | 'address' | 'qr'
  const [dept, setDept] = useState(0);

  const closeModal = () => setModal(null);

  return (
    <section id="chikitsalaya">
      <img src={IMG_HERO_CHIKITSALAYA} alt="Acharya Shree Chikitsalaya" className="vsd-section-hero" />
      <div className="vsd-section">
        <SectionHeading eyebrow="आचार्य चिकित्सालय" title="Acharya Shri Chikitsalaya" />

        <div className="vsd-pillnav">
          {[
            ["intro", "Introduction"],
            ["departments", "Departments"],
          ].map(([k, l]) => (
            <button key={k} className={"vsd-pill" + (tab === k ? " active" : "")} onClick={() => setTab(k)}>
              {l}
            </button>
          ))}
          <button className="vsd-pill" onClick={() => setModal("bank")}>Bank Details</button>
          <button className="vsd-pill" onClick={() => setModal("contact")}>Contact</button>
          <button className="vsd-pill" onClick={() => setModal("address")}>Address</button>
          <a className="vsd-pill" href={HOSPITAL.mapLink} target="_blank" rel="noopener noreferrer">Location</a>
          <button className="vsd-pill vsd-pill-gold" onClick={() => setModal("trust")}>Our Trust</button>
        </div>

        {tab === "intro" && (
          <div className="vsd-fade">
            <div className="vsd-card">
              <p>
                समाज के दुःखी, निर्धन एवं जरूरतमंद रोगियों को सुलभ, शुद्ध और न्यूनतम शुल्क में उत्तम स्वास्थ्य सेवा
                उपलब्ध कराने के उद्देश्य से आचार्य श्री चिकित्सालय की स्थापना की गई है। यहाँ आयुर्वेदिक व सामान्य
                चिकित्सा, निदान केंद्र और आपातकालीन सुविधाएं एक ही परिसर में उपलब्ध हैं, जिससे दक्षिण भारत के
                जैन-जैनेत्तर समाज को गुणवत्तापूर्ण उपचार मिल सके। संत-सज्जनों के आशीर्वाद और ट्रस्ट के समर्पित
                सदस्यों के सहयोग से यह चिकित्सालय निरंतर सेवा-कार्य में अग्रसर है।
              </p>
            </div>
          </div>
        )}

        {tab === "departments" && (
          <div className="vsd-fade">
            <div className="vsd-pillnav vsd-pillnav-sub">
              {DEPARTMENTS.map((d, i) => (
                <button key={i} className={"vsd-pill vsd-pill-sm" + (dept === i ? " active" : "")} onClick={() => setDept(i)}>
                  {d.short}
                </button>
              ))}
            </div>
            <div className="vsd-dept-card">
              <div className="vsd-dept-img-wrap">
                <img src={DEPARTMENTS[dept].image} alt={DEPARTMENTS[dept].title} className="vsd-dept-img" />
                {DEPARTMENTS[dept].signboard && (
                  <div className="vsd-signboard">{DEPARTMENTS[dept].signboard}</div>
                )}
              </div>
              <h3>{DEPARTMENTS[dept].title}</h3>
              <ul>
                {DEPARTMENTS[dept].points.map((p, i) => (
                  <li key={i}>{p}</li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {modal === "trust" && (
          <Modal title="निदेशक मंडल — Our Trust" onClose={closeModal}>
            <TrustTable rows={TRUST_MEMBERS_HOSPITAL} />
          </Modal>
        )}
        {modal === "bank" && (
          <Modal title="Bank Details" onClose={closeModal}><BankModalContent org={HOSPITAL} /></Modal>
        )}
        {modal === "contact" && (
          <Modal title="Contact" onClose={closeModal}><ContactModalContent org={HOSPITAL} /></Modal>
        )}
        {modal === "address" && (
          <Modal title="Address" onClose={closeModal}><AddressModalContent org={HOSPITAL} /></Modal>
        )}
      </div>
    </section>
  );
}

/* ---------- Veeracharya Academy ---------- */

function AcademySection() {
  const [modal, setModal] = useState(null); // 'trust' | 'achievers' | 'bank' | 'contact' | 'address' | 'qr'
  const closeModal = () => setModal(null);

  return (
    <section id="academy">
      <img src={IMG_HERO_ACADEMY} alt="Veeracharya Academy" className="vsd-section-hero" />
      <div className="vsd-section vsd-academy">
        <SectionHeading eyebrow="वीराचार्य अकादमी" title="Veeracharya Academy" />

        <div className="vsd-pillnav">
          <button className="vsd-pill" onClick={() => setModal("achievers")}>Administrative Officer Students</button>
          <button className="vsd-pill" onClick={() => setModal("bank")}>Bank Details</button>
          <button className="vsd-pill" onClick={() => setModal("contact")}>Contact</button>
          <button className="vsd-pill" onClick={() => setModal("address")}>Address</button>
          <a className="vsd-pill" href={ACADEMY.mapLink} target="_blank" rel="noopener noreferrer">Location</a>
          <button className="vsd-pill vsd-pill-gold" onClick={() => setModal("trust")}>Our Trust</button>
        </div>

        <div className="vsd-card">
          <h4>संस्था के उद्देश</h4>
          <ul className="vsd-uddesh-list">
            {UDDESH.map((u, i) => (
              <li key={i}>{u}</li>
            ))}
          </ul>
        </div>

        {modal === "trust" && (
          <Modal title="वीराचार्य अकादमी — Our Trust" onClose={closeModal}>
            <h4 style={{ color: "var(--navy)", margin: "6px 0" }}>निदेशक मंडल</h4>
            <TrustTable rows={ACADEMY_DIRECTORS} />
            <h4 style={{ color: "var(--navy)", margin: "18px 0 6px" }}>सलाहकार मंडल</h4>
            <TrustTable rows={ACADEMY_ADVISORS} />
          </Modal>
        )}
        {modal === "achievers" && (
          <Modal title="Administrative Officer Students" onClose={closeModal}>
            <p className="vsd-achievers-intro">
              {ACADEMY_STUDENTS.length} students from Veeracharya Academy who have gone on to become
              Administrative Officers and government officials.
            </p>
            <div className="vsd-student-grid">
              {ACADEMY_STUDENTS.map((s, i) => (
                <div className="vsd-student-card" key={i}>
                  <img src={s.img} alt={s.name} className="vsd-student-photo" />
                  <div className="vsd-student-name">{s.name}</div>
                  <div className="vsd-student-desig">{s.desig}</div>
                  <div className="vsd-student-village">({s.village})</div>
                </div>
              ))}
            </div>
          </Modal>
        )}
        {modal === "bank" && (
          <Modal title="Bank Details" onClose={closeModal}><BankModalContent org={ACADEMY} /></Modal>
        )}
        {modal === "contact" && (
          <Modal title="Contact" onClose={closeModal}><ContactModalContent org={ACADEMY} /></Modal>
        )}
        {modal === "address" && (
          <Modal title="Address" onClose={closeModal}><AddressModalContent org={ACADEMY} /></Modal>
        )}
      </div>
    </section>
  );
}

/* ---------- top-level page ---------- */

export default function VidyasanmatidasTrustPage() {
  const [main, setMain] = useState("home");

  return (
    <div className="vsd-root">
      <style>{CSS}</style>

      <nav className="vsd-topnav">
        <div className="vsd-brand">विद्यासन्मतीदास सेवा संस्था</div>
        <div className="vsd-navlinks">
          <button className={main === "home" ? "active" : ""} onClick={() => setMain("home")}>होम</button>
          <button className={main === "chikitsalaya" ? "active" : ""} onClick={() => setMain("chikitsalaya")}>आचार्य चिकित्सालय</button>
          <button className={main === "academy" ? "active" : ""} onClick={() => setMain("academy")}>वीराचार्य अकादमी</button>
        </div>
      </nav>

      {main === "home" && (
        <>
          <Hero />
          <HomePage />
        </>
      )}
      {main === "chikitsalaya" && <ChikitsalayaSection />}
      {main === "academy" && <AcademySection />}

      <footer className="vsd-footer">
        <p>अहिंसा से सुख, त्याग से शांति। मैत्री से प्रगती, ध्यान से सिद्धी।।</p>
      </footer>
    </div>
  );
}

const CSS = `
.vsd-root {
  --bg: #f5f9fb;
  --white: #ffffff;
  --navy: #184971;
  --ink: #1d293d;
  --teal: #2fb8c9;
  --teal-light: #8fe0d3;
  --blue: #4da3f7;
  --blue-deep: #2f86d6;
  --sky: #7cc9e8;
  --red: #e53935;
  --light-teal-bg: #eaf7f6;
  font-family: 'Poppins', 'Noto Sans Devanagari', sans-serif;
  background: var(--bg);
  color: var(--ink);
  min-height: 100vh;
}
.vsd-topnav {
  position: sticky; top: 0; z-index: 40;
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 28px;
  background: linear-gradient(90deg, #ffffff 0%, var(--teal-light) 45%, var(--sky) 100%);
  box-shadow: 0 2px 14px rgba(24,73,113,0.15);
}
.vsd-brand { color: var(--navy); font-weight: 700; font-size: 1.05rem; letter-spacing: .02em; }
.vsd-navlinks { display: flex; gap: 4px; }
.vsd-navlinks button {
  background: none; border: none; border-bottom: 2px solid transparent;
  color: var(--ink); padding: 8px 14px; cursor: pointer;
  font-size: .92rem; font-weight: 600; transition: all .25s ease;
}
.vsd-navlinks button:hover { color: var(--navy); }
.vsd-navlinks button.active { color: var(--navy); border-bottom-color: var(--navy); }
@media (max-width: 700px) {
  .vsd-topnav { display: block; padding: 12px 14px; }
  .vsd-brand { text-align: center; font-size: .95rem; margin-bottom: 8px; }
  .vsd-navlinks { justify-content: center; overflow-x: auto; gap: 2px; }
  .vsd-navlinks button { white-space: nowrap; font-size: .78rem; padding: 7px 9px; }
}

.vsd-hero { width: 100%; background: var(--white); display:flex; justify-content:center; }
.vsd-hero-img { width: 100%; max-width: 900px; display: block; }

.vsd-section-hero { width: 100%; max-height: 420px; object-fit: cover; display: block; }

.vsd-section { max-width: 980px; margin: 0 auto; padding: 48px 24px 24px; }
.vsd-heading { text-align: center; margin: 40px 0 26px; }
.vsd-eyebrow { color: var(--red); font-weight: 700; letter-spacing: .14em; text-transform: uppercase; font-size: .78rem; }
.vsd-heading h2 { font-size: 1.9rem; margin: 6px 0 10px; color: var(--ink); }
.vsd-rule { width: 80px; height: 4px; background: linear-gradient(90deg, var(--teal), var(--blue)); margin: 0 auto; border-radius: 4px; }

.vsd-pillnav { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 26px; }
.vsd-pillnav-sub { margin-bottom: 18px; }
.vsd-pill {
  border: 1.5px solid var(--teal); background: #fff; color: var(--navy);
  padding: 10px 20px; border-radius: 999px; cursor: pointer; font-size: .92rem; font-weight: 600;
  transition: all .25s ease;
}
.vsd-pill:hover { background: var(--light-teal-bg); }
.vsd-pill.active { background: linear-gradient(90deg, var(--teal), var(--blue)); color: #fff; border-color: transparent; box-shadow: 0 6px 16px rgba(47,184,201,0.3); }
.vsd-pill-sm { padding: 7px 14px; font-size: .8rem; }
.vsd-pill-gold { border-color: var(--blue); color: #fff; background: var(--blue); }
.vsd-pill-gold:hover, .vsd-pill-gold.active { background: var(--blue-deep); border-color: var(--blue-deep); }

.vsd-card {
  background: #fff; border-radius: 16px; padding: 26px 28px; margin-bottom: 20px;
  box-shadow: 0 8px 24px rgba(24,73,113,0.08); border: 1px solid rgba(24,73,113,0.08);
  line-height: 1.9; font-size: 1rem;
}
.vsd-card h4 { color: var(--navy); margin: 0 0 12px; font-size: 1.05rem; }
.vsd-card h4:not(:first-child) { margin-top: 20px; }
.vsd-fade { animation: vsdFade .4s ease; }
@keyframes vsdFade { from { opacity: 0; transform: translateY(6px);} to { opacity: 1; transform: translateY(0);} }

.vsd-dept-card { background: #fff; border-radius: 16px; padding: 24px; box-shadow: 0 8px 24px rgba(24,73,113,0.08); }
.vsd-dept-img-wrap { position: relative; margin-bottom: 18px; }
.vsd-dept-img { width: 100%; border-radius: 12px; display: block; }
.vsd-signboard {
  position: absolute; left: 50%; bottom: 14px; transform: translateX(-50%);
  background: rgba(24,73,113,0.9); color: #fff; border: 1px solid var(--teal);
  padding: 10px 18px; border-radius: 8px; font-size: .85rem; text-align: center;
  max-width: 92%; line-height: 1.5; font-weight: 600; box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}
.vsd-dept-card h3 { color: var(--navy); font-size: 1.15rem; margin-bottom: 12px; }
.vsd-dept-card ul { padding-left: 20px; line-height: 1.9; }

.vsd-fullwidth-img { width: 100%; border-radius: 14px; box-shadow: 0 10px 28px rgba(24,73,113,0.15); margin-bottom: 18px; display: block; }

.vsd-campus-section { margin-bottom: 40px; }
.vsd-campus-section h4 {
  color: var(--navy); font-size: 1.2rem; font-weight: 800; margin: 0 0 16px; text-align: center;
  letter-spacing: .01em; line-height: 1.5;
}

.vsd-achievers-wrap { display: flex; flex-direction: column; gap: 16px; }
.vsd-achievers-banner {
  display: flex; gap: 10px; justify-content: center; flex-wrap: wrap;
}
.vsd-achievers-banner span {
  background: linear-gradient(90deg, var(--teal), var(--blue)); color: #fff; font-weight: 700;
  padding: 8px 18px; border-radius: 999px; font-size: .85rem; box-shadow: 0 4px 12px rgba(47,184,201,0.25);
}
.vsd-achievers-intro { text-align: center; line-height: 1.8; color: var(--ink); }
.vsd-achievers-frame {
  border: 3px solid var(--teal-light); border-radius: 16px; padding: 8px; background: var(--light-teal-bg);
}

.vsd-qr-row { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
.vsd-qr-img { width: 200px; max-width: 42%; flex: 0 0 auto; border-radius: 8px; box-shadow: 0 6px 18px rgba(24,73,113,0.12); display: block; }
.vsd-qr-msg { flex: 1 1 220px; min-width: 200px; }
.vsd-qr-label { display: inline-block; font-size: .8rem; font-weight: 700; color: #fff; background: var(--navy); padding: 6px 14px; border-radius: 999px; margin-bottom: 10px; }
.vsd-qr-msg p { margin: 0; line-height: 1.8; color: var(--ink); font-size: 1rem; }
@media (max-width: 480px) { .vsd-qr-row { justify-content: center; text-align: center; } }

.vsd-uddesh-list { padding-left: 20px; line-height: 2; }

.vsd-achievers-img { width: 100%; border-radius: 12px; box-shadow: 0 6px 18px rgba(24,73,113,0.12); }

.vsd-modal-backdrop {
  position: fixed; inset: 0; background: rgba(24,41,61,0.55); backdrop-filter: blur(2px);
  display: flex; align-items: center; justify-content: center; z-index: 100; padding: 20px;
}
.vsd-modal { background: #fff; border-radius: 18px; max-width: 860px; width: 100%; max-height: 82vh; overflow: auto; padding: 22px 24px; box-shadow: 0 20px 60px rgba(0,0,0,0.3); }
.vsd-modal-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
.vsd-modal-head h3 { color: var(--navy); }
.vsd-close { background: none; border: none; font-size: 1.6rem; cursor: pointer; color: var(--teal); line-height: 1; }

.vsd-table-wrap { overflow-x: auto; }
.vsd-table { width: 100%; border-collapse: collapse; font-size: .88rem; }
.vsd-table th { background: var(--navy); color: #fff; padding: 10px 12px; text-align: left; }
.vsd-table td { padding: 9px 12px; border-bottom: 1px solid #e3f2f4; }
.vsd-table tr:nth-child(even) td { background: var(--light-teal-bg); }

.vsd-footer { text-align: center; padding: 30px; color: #fff; font-weight: 600; background: var(--navy); margin-top: 30px; }

.vsd-student-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; }
.vsd-student-card {
  background: #fff; border: 1px solid rgba(24,73,113,0.1); border-radius: 14px; overflow: hidden;
  box-shadow: 0 6px 16px rgba(24,73,113,0.08); display: flex; flex-direction: column;
}
.vsd-student-photo { width: 100%; aspect-ratio: 4 / 4.6; object-fit: cover; display: block; background: var(--light-teal-bg); }
.vsd-student-name { font-weight: 800; color: var(--navy); font-size: .95rem; padding: 10px 12px 2px; }
.vsd-student-desig { font-weight: 700; color: var(--ink); font-size: .82rem; padding: 2px 12px; line-height: 1.5; }
.vsd-student-village { font-size: .78rem; color: var(--teal); font-weight: 600; padding: 4px 12px 12px; }
@media (max-width: 520px) { .vsd-student-grid { grid-template-columns: 1fr; } }

.vsd-map-wrap { display: flex; flex-direction: column; gap: 14px; }
.vsd-map-frame { width: 100%; height: 320px; border: 0; border-radius: 12px; box-shadow: 0 6px 18px rgba(24,73,113,0.12); }
.vsd-map-btn {
  align-self: flex-start; background: var(--blue); color: #fff; font-weight: 700; text-decoration: none;
  padding: 10px 20px; border-radius: 999px; font-size: .88rem; transition: background .2s ease;
}
.vsd-map-btn:hover { background: var(--blue-deep); }
`;
